using System.Linq;using UnityEngine;using UnityEditor;
public static class InspectNativeCurves{public static string Run(){return string.Join("\n",new[]{"Gronk","Chief","Guardian"}.Select(n=>{var p=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Research/MuckNative/GameObject/"+n+".prefab");return n+" root="+p.transform.localScale+"\n"+string.Join("\n",p.GetComponentsInChildren<Transform>(true).Take(7).Select(t=>t.name+" "+t.localPosition+" "+t.localScale))+"\n"+string.Join("\n",AssetDatabase.FindAssets("t:AnimationClip",new[]{"Assets/Resources/ExpeditionEnemies/MuckNative"}).Select(AssetDatabase.GUIDToAssetPath).Where(x=>x.Contains(n+"_")).Select(x=>{var c=AssetDatabase.LoadAssetAtPath<AnimationClip>(x);return c.name+" "+string.Join(";",AnimationUtility.GetCurveBindings(c).Where(b=>b.path==""||b.propertyName.Contains("Scale")).Select(b=>b.path+" "+b.propertyName));}));}));}}
